import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import "./optimizevideo.css";

const Optimizevideo_shortform = () => {
  const location = useLocation();
  const [videoPath, setVideoPath] = useState("");
  const [message, setMessage] = useState("");
  const [selectedFeatures, setSelectedFeatures] = useState([]);

  useEffect(() => {
    if (location.state) {
      const { videoURL, results = {}, features = [] } = location.state;
      console.log("Received Results:", results);
      setSelectedFeatures(features);

      // Extract paths from results
      const audioProcessedPath = results.audio_processing?.enhanced_video_path;
      const videoOptimizedPath = results.video_upscaling?.output_path;

      // Determine which path to use (prefer audio processed if available)
      const selectedPath = audioProcessedPath || videoOptimizedPath;

      if (selectedPath) {
        // Extract just the filename from the full path
        const filename = selectedPath.split('\\').pop();

        if (filename) {
          setVideoPath(`http://127.0.0.1:8000/media/${filename}`);
          setMessage("Video processing completed successfully!");
        }
      } else {
        setMessage("No processed video available.");
      }
    }
  }, [location.state]);

  const handleDownload = () => {
    if (videoPath) {
      const link = document.createElement("a");
      link.href = videoPath;
      link.download = "optimized-shortform-video.mp4";
      link.click();
    }
  };

  return (
    <div className="optimized-video-page">
      <header className="page-header">
        <h1>Optimized Short-form Video</h1>
        <p>{message}</p>
      </header>

      <div className="features-section">
        <h2>Applied Optimizations</h2>
        <div className="features-list">
          {selectedFeatures.length > 0 ? (
            selectedFeatures.map((feature, index) => (
              <span key={index} className="feature-tag">
                {feature}
              </span>
            ))
          ) : (
            <p>No optimization features selected</p>
          )}
        </div>
      </div>

      <div className="video-output">
        {videoPath ? (
          <>
            <video className="optimized-video" controls src={videoPath}>
              Your browser does not support the video tag.
            </video>
            <div className="video-info">
              <p>Processing Status: {message}</p>
              <div className="action-buttons">
                <button
                  className="download-button"
                  onClick={handleDownload}
                >
                  Download Optimized Video
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="no-video">
            <p>No optimized video available.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Optimizevideo_shortform;
